+static bool prepare_restore_callback(crlib_conf_t *conf, void *user_data) {
+  const CracEngine *engine = const_cast<const CracEngine *>(static_cast<CracEngine *>(user_data));
+  return engine->prepare_restore_callback(conf);
+}
